@import url('https://fonts.googleapis.com/css2?family=Graduate&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Denver Broncos DNA — Predominantly orange, mile-high navy. */
.theme-denver-broncos {
  --bg: oklch(0.225 0.051 255.6);
  --surface: oklch(0.273 0.069 256.4);
  --surface-2: oklch(0.322 0.084 255.9);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.623 0.143 255.6);
  --accent: oklch(0.664 0.217 36.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.696 0.089 257.4);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.375rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Graduate", serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.04em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-denver-broncos h1,
.theme-denver-broncos h2,
.theme-denver-broncos h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-denver-broncos { --font-ui: var(--font-display); }
.theme-denver-broncos h1, .theme-denver-broncos h2 { text-transform: uppercase; }
.theme-denver-broncos h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-denver-broncos button { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 600; }
.theme-denver-broncos th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.12em; font-size: 11px; border-bottom: 2px solid var(--accent); }
.theme-denver-broncos tbody tr:hover { background: color-mix(in oklab, var(--accent) 8%, transparent); }
.theme-denver-broncos h2 { border-bottom: 3px solid var(--accent); display: inline-block; padding-bottom: 0.15em; }
.theme-denver-broncos ::selection { background: var(--accent); color: var(--accent-fg); }


/* alt mode: road whites */
.theme-denver-broncos.alt-mode {
  --bg: oklch(0.975 0.004 255); --surface: oklch(1 0 0); --surface-2: oklch(0.93 0.008 255);
  --fg: oklch(0.24 0.05 255); --fg-muted: oklch(0.44 0.06 255); --line: oklch(0.88 0.01 255);
  --accent: oklch(0.664 0.217 36.5); --accent-fg: oklch(1.000 0 0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%); --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%); --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-denver-broncos.alt-mode h1 { color: oklch(0.664 0.217 36.5); }
.theme-denver-broncos.alt-mode h2, .theme-denver-broncos.alt-mode h3 { color: oklch(0.3 0.07 255); }
.theme-denver-broncos.alt-mode h2 { border-bottom-color: oklch(0.3 0.07 255); }
.theme-denver-broncos.alt-mode th { color: oklch(0.38 0.07 255); border-bottom-color: oklch(0.38 0.07 255); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
